// Data access. Two modes:
//  - demo: no NEXT_PUBLIC_API_URL. Uses a demo repo graph (DEMO_REPOS), runs the
//    impact engine in the browser, and simulates runs.
//  - live: NEXT_PUBLIC_API_URL points at the FastAPI server (PRD section 13).

import { computeImpact } from "@/lib/impact";
import marketplaceGraph from "@/lib/mock/marketplace-dashboard.graph.json";
import { shopflowGraph } from "@/lib/mock/shopflow";
import type { ChangeRequest, DataMode, Graph, ImpactReport, RunEvent } from "@/lib/types";

export const API_URL = process.env.NEXT_PUBLIC_API_URL?.replace(/\/$/, "") || "";
export const DATA_MODE: DataMode = API_URL ? "live" : "demo";
const DEMO_TOKEN = process.env.NEXT_PUBLIC_DEMO_TOKEN || "";

async function http<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(`${API_URL}${path}`, {
    ...init,
    headers: {
      "Content-Type": "application/json",
      ...(DEMO_TOKEN ? { Authorization: `Bearer ${DEMO_TOKEN}` } : {}),
      ...init?.headers,
    },
  });
  if (!res.ok) throw new Error(`${init?.method ?? "GET"} ${path} failed: ${res.status}`);
  return res.json() as Promise<T>;
}

export interface DemoRepo {
  id: string;
  label: string;
  description: string;
  graph: Graph;
  /** The change the New change form starts with. */
  defaultChange: { node: string; to: string };
}

// Demo repos. The marketplace graph is real: it was produced by
// core/scanner/ts-scan.mjs from github.com/krishil-agrawal-itp/marketplace-dashboard.
export const DEMO_REPOS: DemoRepo[] = [
  {
    id: "marketplace-dashboard",
    label: "marketplace-dashboard",
    description: "Next.js + TypeScript. Scanned with the TypeScript compiler.",
    graph: marketplaceGraph as Graph,
    defaultChange: { node: "field:Deployment.successRate", to: "deploySuccessRate" },
  },
  {
    id: "shopflow",
    label: "samples/shopflow",
    description: "Hand-made 7-layer sample from the PRD (SQL, PySpark, API, React).",
    graph: shopflowGraph,
    defaultChange: { node: "db:column:orders.cust_id", to: "customer_id" },
  },
];

export function demoRepo(id: string | undefined): DemoRepo {
  return DEMO_REPOS.find((r) => r.id === id) ?? DEMO_REPOS[0];
}

export async function fetchGraph(repoId?: string): Promise<Graph> {
  if (DATA_MODE === "demo") return demoRepo(repoId).graph;
  return http<Graph>("/graph");
}

/** Works out the impact. In live mode the server also creates the change. */
export async function analyseChange(
  graph: Graph,
  request: ChangeRequest,
): Promise<{ report: ImpactReport; changeId?: string }> {
  if (DATA_MODE === "demo") return { report: computeImpact(graph, request) };
  const res = await http<{ change_id: string; report: ImpactReport }>("/changes", {
    method: "POST",
    body: JSON.stringify(request),
  });
  return { report: res.report, changeId: res.change_id };
}

export async function runChange(changeId: string) {
  await http(`/changes/${encodeURIComponent(changeId)}/run`, { method: "POST" });
}

export async function approveChange(changeId: string) {
  await http(`/changes/${encodeURIComponent(changeId)}/approve`, { method: "POST" });
}

/** Opens the live event feed. Returns a function that closes it. */
export function subscribeEvents(
  onEvent: (ev: RunEvent) => void,
  onStatus: (s: "open" | "closed") => void,
): () => void {
  if (DATA_MODE === "demo") return () => {};
  const wsUrl = API_URL.replace(/^http/, "ws") + "/ws";
  let ws: WebSocket | null = null;
  let stopped = false;
  let retry: ReturnType<typeof setTimeout> | undefined;

  const connect = () => {
    ws = new WebSocket(wsUrl);
    ws.onopen = () => onStatus("open");
    ws.onmessage = (msg) => {
      try {
        onEvent(JSON.parse(msg.data) as RunEvent);
      } catch {
        // Ignore messages that are not events.
      }
    };
    ws.onclose = () => {
      onStatus("closed");
      if (!stopped) retry = setTimeout(connect, 2000);
    };
  };
  connect();
  return () => {
    stopped = true;
    clearTimeout(retry);
    ws?.close();
  };
}

// Shared types for the SystemDNA dashboard.
// They follow the PRD contracts: graph.json (section 7), the impact report
// (section 8) and the event schema (section 13).

/**
 * A district on the city map. Each repo defines its own layers.
 * Two ids have fixed meaning: "business" (read-only processes) and
 * "quality" (tests and docs, drawn as a row under the city).
 */
export type LayerId = string;

export interface LayerDef {
  id: LayerId;
  label: string;
  /** Column on the city map. -1 = the row under the city. */
  column: number;
  /** Edits here need a human approval (database, shared type contracts). */
  requiresApproval?: boolean;
  /** What the verify step checks for files in this layer. */
  check?: string;
}

export type NodeType =
  | "Table"
  | "Column"
  | "SQLModel"
  | "SparkJob"
  | "Module"
  | "Function"
  | "ORMModel"
  | "Schema"
  | "Field"
  | "Endpoint"
  | "TSType"
  | "TSField"
  | "Component"
  | "Dashboard"
  | "Dataset"
  | "Constant"
  | "Page"
  | "Test"
  | "Doc"
  | "BusinessProcess";

export type EdgeType =
  | "DERIVES_FROM"
  | "READS"
  | "WRITES"
  | "MAPS_TO"
  | "SERIALIZES"
  | "RETURNS"
  | "CONSUMES"
  | "TYPED_AS"
  | "IMPORTS"
  | "CALLS"
  | "TESTS"
  | "DOCUMENTS"
  | "SUPPORTS";

/** How to fix an edge when its upstream side changes. */
export type EdgeRule =
  | "rename_ref"
  | "keep_alias"
  | "update_type"
  | "update_doc"
  | "passthrough";

export type Confidence = "high" | "medium" | "low";

export interface GraphNode {
  id: string;
  type: NodeType;
  layer: LayerId;
  name: string;
  file: string;
  line?: number;
  /** Asset that holds this node (a column's table, a field's model). */
  parent?: string;
  owner?: string;
  pii: boolean;
  criticality: "low" | "medium" | "high";
  tested: boolean;
  /** Identifiers that appear as plain text in the file. Used by the grep comparison. */
  tokens?: string[];
}

/** An edge points downstream: `to` depends on `from`. */
export interface GraphEdge {
  id: string;
  from: string;
  to: string;
  type: EdgeType;
  source: "parser" | "bob";
  confidence: Confidence;
  evidence: string;
  rule: EdgeRule;
}

/** One file in the repo. The 3D city draws one building per file. */
export interface RepoFile {
  path: string;
  /** Top-level folder, or "root" for files at the top. */
  dir: string;
  /** Non-blank lines. */
  lines: number;
  language: string;
  /** Local files this file imports. */
  imports: string[];
}

export interface Graph {
  repo: string;
  scannedAt: string;
  layers: LayerDef[];
  nodes: GraphNode[];
  edges: GraphEdge[];
  /** Word -> files that contain it as plain text. Used by the grep comparison. */
  textIndex?: Record<string, string[]>;
  /** Per-file data from the scanner. Graphs without it get estimated files. */
  files?: RepoFile[];
}

export type ChangeKind = "rename" | "type_change" | "delete";

export interface ChangeRequest {
  node: string;
  change: ChangeKind;
  to: string;
}

export type Severity = "breaking" | "needs_update" | "update" | "safe";

export interface ImpactItem {
  nodeId: string;
  severity: Severity;
  /** Longest path from the changed node. 0 = the changed node itself. */
  depth: number;
  risk: number;
  viaEdge?: string;
  confidence: Confidence;
  needsApproval: boolean;
}

/** One file that one agent will fix. `id` is the file path. */
export interface FixUnit {
  id: string;
  assetName: string;
  file: string;
  layer: LayerId;
  /** Map buildings (asset ids) that live in this file. */
  assets: string[];
  nodes: string[];
  wave: number;
  needsApproval: boolean;
  approvalReason?: string;
}

export interface ImpactReport {
  request: ChangeRequest;
  oldName: string;
  items: ImpactItem[];
  fixUnits: FixUnit[];
  waveCount: number;
  business: { nodeId: string; name: string; owner?: string; severity: Severity }[];
  /** File paths. */
  grep: { found: string[]; missed: string[]; falsePositives: string[] };
  /** Node ids grouped by depth, for the ripple animation. */
  levels: string[][];
  danglingRefs: number;
  computedMs: number;
}

export type RunEventType =
  | "impact_ready"
  | "awaiting_approval"
  | "approved"
  | "wave_started"
  | "agent_started"
  | "tool_call"
  | "blocked"
  | "check_passed"
  | "check_failed"
  | "retrying"
  | "done"
  | "quarantined"
  | "wave_completed"
  | "rescan"
  | "inspector"
  | "pr_created"
  | "change_completed";

export interface RunEvent {
  ts: string;
  change_id: string;
  event: RunEventType;
  agent_id?: string;
  session_id?: string;
  wave?: number;
  tool?: string;
  file?: string;
  /** Fix unit id (asset id). */
  node?: string;
  permit_ok?: boolean;
  detail?: string;
  bobcoins?: number;
  data?: Record<string, string | number | boolean>;
}

export type DataMode = "demo" | "live";

export interface Change {
  id: string;
  /** Graph.repo this change belongs to. */
  repo?: string;
  title: string;
  request: ChangeRequest;
  report: ImpactReport;
  createdAt: string;
  mode: DataMode;
  events: RunEvent[];
}

"use client";

import { useMemo } from "react";
import { create } from "zustand";
import { createJSONStorage, persist } from "zustand/middleware";
import { DATA_MODE, DEMO_REPOS, fetchGraph } from "@/lib/api";
import type { Change, Graph, RunEvent } from "@/lib/types";

interface AppState {
  graph: Graph | null;
  graphError: string | null;
  changes: Change[];
  hydrated: boolean;
  /** Demo repo id (demo mode only). */
  repoId: string;
  setRepo: (id: string) => Promise<void>;
  loadGraph: () => Promise<void>;
  addChange: (change: Change) => void;
  appendEvent: (ev: RunEvent) => void;
  resetEvents: (changeId: string) => void;
  resetDemo: () => void;
  nextChangeId: () => string;
}

export const useApp = create<AppState>()(
  persist(
    (set, get) => ({
      graph: null,
      graphError: null,
      changes: [],
      hydrated: false,
      repoId: DEMO_REPOS[0].id,
      setRepo: async (id) => {
        set({ repoId: id, graph: null });
        await get().loadGraph();
      },
      loadGraph: async () => {
        if (get().graph) return;
        try {
          set({ graph: await fetchGraph(get().repoId), graphError: null });
        } catch (err) {
          set({ graphError: err instanceof Error ? err.message : "Could not load the graph" });
        }
      },
      addChange: (change) => set((s) => ({ changes: [change, ...s.changes] })),
      appendEvent: (ev) =>
        set((s) => ({
          changes: s.changes.map((c) =>
            c.id === ev.change_id ? { ...c, events: [...c.events, ev] } : c,
          ),
        })),
      resetEvents: (changeId) =>
        set((s) => ({
          changes: s.changes.map((c) => (c.id === changeId ? { ...c, events: [] } : c)),
        })),
      resetDemo: () => set({ changes: [] }),
      nextChangeId: () => {
        const max = get().changes.reduce((m, c) => {
          const n = Number(c.id.replace(/\D/g, ""));
          return Number.isFinite(n) ? Math.max(m, n) : m;
        }, 0);
        return `chg-${String(max + 1).padStart(3, "0")}`;
      },
    }),
    {
      name: `systemdna-${DATA_MODE}`,
      storage: createJSONStorage(() => localStorage),
      partialize: (s) => ({ changes: s.changes, repoId: s.repoId }),
      skipHydration: true,
      onRehydrateStorage: () => () => useApp.setState({ hydrated: true }),
    },
  ),
);

/** Changes that belong to the repo on screen. Older saved changes had no repo: they are ShopFlow's. */
export function useRepoChanges(): Change[] {
  const changes = useApp((s) => s.changes);
  const repo = useApp((s) => s.graph?.repo);
  return useMemo(
    () => (repo ? changes.filter((c) => (c.repo ?? "samples/shopflow") === repo) : []),
    [changes, repo],
  );
}

export function useChange(id: string | undefined) {
  return useApp((s) => s.changes.find((c) => c.id === id));
}
