86 | /** Opens the live event feed. Returns a function that closes it. */
87 | export function subscribeEvents(
88 |   onEvent: (ev: RunEvent) => void,
89 |   onStatus: (s: "open" | "closed") => void,
90 | ): () => void {
91 |   if (DATA_MODE === "demo") return () => {};
92 |   const wsUrl = API_URL.replace(/^http/, "ws") + "/ws";
93 |   let ws: WebSocket | null = null;
94 |   let stopped = false;
95 |   let retry: ReturnType<typeof setTimeout> | undefined;
96 | 
97 |   const connect = () => {
98 |     ws = new WebSocket(wsUrl);
99 |     ws.onopen = () => onStatus("open");
100 |     ws.onmessage = (msg) => {
101 |       try {
102 |         onEvent(JSON.parse(msg.data) as RunEvent);
103 |       } catch {
104 |         // Ignore messages that are not events.
105 |       }
106 |     };
107 |     ws.onclose = () => {
108 |       onStatus("closed");
109 |       if (!stopped) retry = setTimeout(connect, 2000);
110 |     };
111 |   };
112 |   connect();
113 |   return () => {
114 |     stopped = true;
115 |     clearTimeout(retry);
116 |     ws?.close();
117 |   };
118 | }
