1 | // Turns a change's event list into what the run screens show.
2 | // The same function works for demo (simulated) and live (WebSocket) events.
3 | 
4 | import type { Change, RunEvent } from "@/lib/types";
5 | 
6 | export type AgentState =
7 |   | "queued"
8 |   | "awaiting_approval"
9 |   | "reading"
10 |   | "editing"
11 |   | "verifying"
12 |   | "retrying"
13 |   | "blocked"
14 |   | "done"
15 |   | "quarantined";
16 | 
17 | export type BuildingState =
18 |   | "affected"
19 |   | "awaiting_approval"
20 |   | "under_construction"
21 |   | "inspecting"
22 |   | "blocked"
23 |   | "fixed"
24 |   | "needs_human";
25 | 
26 | export type RunStatus = "planned" | "awaiting_approval" | "running" | "completed";
27 | 
28 | export interface AgentView {
29 |   id: string;
30 |   unit: string;
31 |   file: string;
32 |   wave: number;
33 |   state: AgentState;
34 |   lastAction: string;
35 |   bobcoins: number;
36 |   retries: number;
37 |   blocked: number;
38 |   startedAt?: string;
39 |   endedAt?: string;
40 | }
41 | 
42 | export interface RunView {
43 |   status: RunStatus;
44 |   startedAt?: string;
45 |   endedAt?: string;
46 |   elapsedMs: number;
47 |   currentWave: number;
48 |   waveCount: number;
49 |   agents: AgentView[];
50 |   unitState: Record<string, BuildingState>;
51 |   pendingApprovals: { unit: string; file: string; reason: string }[];
52 |   approvals: RunEvent[];
53 |   blocked: RunEvent[];
54 |   checksPassed: number;
55 |   checksFailed: number;
56 |   bobcoins: number;
57 |   danglingBefore?: number;
58 |   danglingAfter?: number;
59 |   inspector?: { verdict: string; issues: number };
60 |   pr?: { branch: string; simulated: boolean };
61 | }
62 | 
63 | const TOOL_STATE: Record<string, AgentState> = {
64 |   read_file: "reading",
65 |   list_files: "reading",
66 |   search_files: "reading",
67 |   write_to_file: "editing",
68 |   apply_diff: "editing",
69 |   execute_command: "verifying",
70 | };
71 | 
72 | export function deriveRun(change: Change, now: number = Date.now()): RunView {
73 |   const units = change.report.fixUnits;
74 |   const unitState: Record<string, BuildingState> = Object.fromEntries(
75 |     units.map((u) => [u.id, "affected" as BuildingState]),
76 |   );
77 |   const agents = new Map<string, AgentView>();
78 |   const pending = new Map<string, { unit: string; file: string; reason: string }>();
79 |   const view: RunView = {
80 |     status: "planned",
81 |     elapsedMs: 0,
82 |     currentWave: 0,
83 |     waveCount: change.report.waveCount,
84 |     agents: [],
85 |     unitState,
86 |     pendingApprovals: [],
87 |     approvals: [],
88 |     blocked: [],
89 |     checksPassed: 0,
90 |     checksFailed: 0,
91 |     bobcoins: 0,
92 |   };
93 | 
94 |   for (const ev of change.events) {
95 |     if (!view.startedAt && ev.event !== "impact_ready") view.startedAt = ev.ts;
96 |     const agent = ev.agent_id ? agents.get(ev.agent_id) : undefined;
97 |     if (ev.bobcoins) view.bobcoins += ev.bobcoins;
98 | 
99 |     switch (ev.event) {
100 |       case "awaiting_approval":
101 |         if (ev.node) {
102 |           pending.set(ev.node, { unit: ev.node, file: ev.file ?? "", reason: ev.detail ?? "" });
103 |           unitState[ev.node] = "awaiting_approval";
104 |         }
105 |         view.status = "awaiting_approval";
106 |         break;
107 |       case "approved":
108 |         if (ev.node) {
109 |           pending.delete(ev.node);
110 |           unitState[ev.node] = "affected";
111 |         }
112 |         view.approvals.push(ev);
113 |         if (pending.size === 0) view.status = "running";
114 |         break;
115 |       case "wave_started":
116 |         view.status = "running";
117 |         view.currentWave = ev.wave ?? view.currentWave;
118 |         break;
119 |       case "agent_started":
120 |         if (ev.agent_id && ev.node) {
121 |           agents.set(ev.agent_id, {
122 |             id: ev.agent_id,
123 |             unit: ev.node,
124 |             file: ev.file ?? "",
125 |             wave: ev.wave ?? view.currentWave,
126 |             state: "queued",
127 |             lastAction: "Permit issued",
128 |             bobcoins: 0,
129 |             retries: 0,
130 |             blocked: 0,
131 |             startedAt: ev.ts,
132 |           });
133 |         }
134 |         break;
135 |       case "tool_call":
136 |         if (agent) {
137 |           agent.state = TOOL_STATE[ev.tool ?? ""] ?? agent.state;
138 |           agent.lastAction = `${ev.tool} ${ev.file ?? ""}`.trim();
139 |           unitState[agent.unit] = "under_construction";
140 |         }
141 |         break;
142 |       case "blocked":
143 |         view.blocked.push(ev);
144 |         if (agent) {
145 |           agent.state = "blocked";
146 |           agent.blocked += 1;
147 |           agent.lastAction = ev.detail ?? "Blocked by permit";
148 |           unitState[agent.unit] = "blocked";
149 |         }
150 |         break;
151 |       case "check_failed":
152 |         view.checksFailed += 1;
153 |         if (agent) {
154 |           agent.state = "verifying";
155 |           agent.lastAction = ev.detail ?? "Check failed";
156 |           unitState[agent.unit] = "needs_human";
157 |         }
158 |         break;
159 |       case "retrying":
160 |         if (agent) {
161 |           agent.state = "retrying";
162 |           agent.retries += 1;
163 |           agent.lastAction = "Retrying with the error message";
164 |           unitState[agent.unit] = "under_construction";
165 |         }
166 |         break;
167 |       case "check_passed":
168 |         view.checksPassed += 1;
169 |         if (agent) {
170 |           agent.state = "verifying";
171 |           agent.lastAction = ev.detail ?? "Checks passed";
172 |           unitState[agent.unit] = "inspecting";
173 |         }
174 |         break;
175 |       case "done":
176 |         if (agent) {
177 |           agent.state = "done";
178 |           agent.lastAction = "Done";
179 |           agent.endedAt = ev.ts;
180 |           unitState[agent.unit] = "fixed";
181 |         }
182 |         break;
183 |       case "quarantined":
184 |         if (agent) {
185 |           agent.state = "quarantined";
186 |           agent.lastAction = ev.detail ?? "Quarantined";
187 |           unitState[agent.unit] = "needs_human";
188 |         }
189 |         break;
190 |       case "rescan":
191 |         view.danglingBefore = Number(ev.data?.before ?? 0);
192 |         view.danglingAfter = Number(ev.data?.after ?? 0);
193 |         break;
194 |       case "inspector":
195 |         view.inspector = {
196 |           verdict: String(ev.data?.verdict ?? "approved"),
197 |           issues: Number(ev.data?.issues ?? 0),
198 |         };
199 |         break;
200 |       case "pr_created":
201 |         view.pr = {
202 |           branch: String(ev.data?.branch ?? ""),
203 |           simulated: Boolean(ev.data?.simulated),
204 |         };
205 |         break;
206 |       case "change_completed":
207 |         view.status = "completed";
208 |         view.endedAt = ev.ts;
209 |         break;
210 |     }
211 |     if (agent && ev.bobcoins) agent.bobcoins += ev.bobcoins;
212 |   }
213 | 
214 |   view.agents = [...agents.values()];
215 |   view.pendingApprovals = [...pending.values()];
216 |   if (view.startedAt) {
217 |     const end = view.endedAt ? Date.parse(view.endedAt) : now;
218 |     view.elapsedMs = Math.max(0, end - Date.parse(view.startedAt));
219 |   }
220 |   return view;
221 | }
222 | 
223 | export function formatDuration(ms: number): string {
224 |   const s = Math.round(ms / 1000);
225 |   const m = Math.floor(s / 60);
226 |   return m > 0 ? `${m}m ${String(s % 60).padStart(2, "0")}s` : `${s}s`;
227 | }
